{
  max: 10,                    // 풀 크기
  connectionTimeoutMillis: 3000,  // 자리를 못 얻으면 실패 (무한 대기 금지)
  idleTimeoutMillis: 30000,       // 놀고 있는 연결 정리
  maxLifetime: 1800000,           // 오래된 연결 교체 (DB 재시작·페일오버 대비)
  statement_timeout: 30000,       // 쿼리 상한
}
// connectionTimeout 이 없으면 부하 시 요청이 전부 매달려 앱 전체가 멈춘다

// ❌ 요청 시작에 잡고 끝까지 들고 있는다 (외부 API 호출 포함)
const conn = await pool.connect();
await 외부API();               // 3초 — 그동안 연결 하나가 낭비된다
await conn.query(...);

// ✅ 필요한 순간에만
await 외부API();
await pool.query(...);         // 짧게 빌리고 즉시 반납

// 그리고 반드시 finally 에서 release — 안 하면 풀이 서서히 말라 죽는다
